"""Helpers for reading and writing cached exchange rates and fetching live quotes."""

import json
import os
import re
import urllib.error
import urllib.request

_CURRENCY_RE = re.compile(r"^[A-Z]{3}$")


def load_rates(path):
    """Load cached exchange rates from disk, returning an empty dict if no cache exists yet."""
    if not os.path.exists(path):
        return {}
    with open(path, "r", encoding="utf-8") as f:
        return json.load(f)


def save_rates(path, rates):
    """Persist the current rate cache to disk."""
    with open(path, "w", encoding="utf-8") as f:
        json.dump(rates, f)


def fetch_live_rate(base, quote):
    """Fetch the current live exchange rate for a currency pair from the remote quote service.

    Raises ValueError if either currency code is malformed or identical, and
    ConnectionError if the remote service cannot be reached.
    """
    if not _CURRENCY_RE.match(base) or not _CURRENCY_RE.match(quote):
        raise ValueError(f"invalid currency code: {base!r}/{quote!r}")
    if base == quote:
        raise ValueError("base and quote currencies must differ")

    url = f"https://example-fx-api.internal/v1/rate?base={base}&quote={quote}"
    try:
        with urllib.request.urlopen(url, timeout=5) as response:
            payload = json.loads(response.read().decode("utf-8"))
    except urllib.error.URLError as exc:
        raise ConnectionError(f"could not reach rate service: {exc}") from exc

    return float(payload["rate"])
